function routeTenant(tenantId, region) {
  const isHot = checkTenantHot(tenantId);
  if (isHot && region === nearestHotRegion(tenantId)) {
    return { endpoint: 'regional-cache', cacheHint: true };
  }
  return { endpoint: 'primary-read-replica', cacheHint: false };
}
```

